var fx = layerDesc().getObjectValue(S2T('layerEffects')), f = fx.getObjectValue(S2T('gradientFill')), st = [[122,78,14,0],[249,231,159,1638],[201,151,28,2253],[255,243,196,2949],[138,90,18,4096]], i;
var g = new ActionDescriptor(); g.putString(C2T('Nm  '), 'plan'); g.putEnumerated(C2T('GrdF'), C2T('GrdF'), C2T('CstS')); g.putDouble(C2T('Intr'), 4096);
var cs = new ActionList(), ts = new ActionList();
for (i = 0; i < st.length; i++) { var c = new ActionDescriptor(), k = new ActionDescriptor(); k.putDouble(C2T('Rd  '), st[i][0]); k.putDouble(C2T('Grn '), st[i][1]); k.putDouble(C2T('Bl  '), st[i][2]);
  c.putObject(C2T('Clr '), C2T('RGBC'), k); c.putEnumerated(C2T('Type'), C2T('Clry'), C2T('UsrS')); c.putInteger(C2T('Lctn'), st[i][3]); c.putInteger(C2T('Mdpn'), 50); cs.putObject(C2T('Clrt'), c); }
for (i = 0; i < 2; i++) { var t = new ActionDescriptor(); t.putUnitDouble(C2T('Opct'), C2T('#Prc'), 100); t.putInteger(C2T('Lctn'), i * 4096); t.putInteger(C2T('Mdpn'), 50); ts.putObject(C2T('TrnS'), t); }
g.putList(C2T('Clrs'), cs); g.putList(C2T('Trns'), ts);
f.putObject(S2T('gradient'), S2T('gradientClassEvent'), g); fx.putObject(S2T('gradientFill'), S2T('gradientFill'), f);
var sd = new ActionDescriptor(); sd.putReference(C2T('null'), fxRef()); sd.putObject(C2T('T   '), S2T('layerEffects'), fx); executeAction(C2T('setd'), sd, DialogModes.NO);

