var lam = 0.99507, k, sh, t;
var typeL = d.layers[1];
L.move(typeL, ElementPlacement.PLACEAFTER);
var bk = d.artLayers.add(); bk.name = 'ramp'; d.activeLayer = bk; d.selection.selectAll(); d.selection.fill(hexc('#000000')); d.selection.deselect();
bk.move(L, ElementPlacement.PLACEAFTER);
var M = L.merge(); M.name = 'ramp';
for (k = 0; k < 9; k++) { sh = Math.pow(2, k); t = M.duplicate(); t.translate(UnitValue(sh, 'px'), UnitValue(sh, 'px'));
  t.adjustLevels(0, 255, 1.0, 0, Math.round(255 * Math.pow(lam, sh))); t.blendMode = BlendMode.LIGHTEN; M = t.merge(); }
var i, vis = [];
for (i = 0; i < d.layers.length; i++) { vis.push(d.layers[i].visible); if (d.layers[i] != M && d.layers[i].name != M.name) d.layers[i].visible = false; }
d.activeLayer = M;
var s = new ActionDescriptor(); s.putReference(C2T('null'), selRef()); var rc = new ActionReference(); rc.putEnumerated(C2T('Chnl'), C2T('Chnl'), C2T('RGB ')); s.putReference(C2T('T   '), rc); executeAction(C2T('setd'), s, DialogModes.NO);
var sl = d.artLayers.add(); sl.name = 'long shadow'; d.activeLayer = sl; d.selection.fill(hexc('#1F3A4D')); d.selection.deselect();
M.remove();
for (i = 0; i < d.layers.length; i++) d.layers[i].visible = true;
sl.move(typeL, ElementPlacement.PLACEAFTER);
say('layers: ' + d.layers.length);

